// Heat diffusion on the GPU.
//
// Usage: deno run --allow-read main.ts <grid-file>
//
// Each step runs a WebGPU compute kernel that replaces every cell with
// (4 * self + left + right + up + down) / 8, reading from one buffer and
// writing to the other so that no cell sees a value written in the same step.

const WORKGROUP = 8;

const SHADER = `
struct Params {
  width: u32,
  height: u32,
}

@group(0) @binding(0) var<uniform> params: Params;
@group(0) @binding(1) var<storage, read> src: array<u32>;
@group(0) @binding(2) var<storage, read_write> dst: array<u32>;

@compute @workgroup_size(${WORKGROUP}, ${WORKGROUP})
fn main(@builtin(global_invocation_id) id: vec3<u32>) {
  let x = id.x;
  let y = id.y;
  if (x >= params.width || y >= params.height) {
    return;
  }

  // Neighbours outside the grid read the nearest cell inside it.
  let xl = select(x - 1u, x, x == 0u);
  let xr = min(x + 1u, params.width - 1u);
  let yu = select(y - 1u, y, y == 0u);
  let yd = min(y + 1u, params.height - 1u);

  let row = y * params.width;
  let sum = 4u * src[row + x]
    + src[row + xl]
    + src[row + xr]
    + src[yu * params.width + x]
    + src[yd * params.width + x];

  dst[row + x] = sum / 8u;
}
`;

function fail(message: string): never {
  console.error(message);
  Deno.exit(1);
}

interface Grid {
  width: number;
  height: number;
  steps: number;
  cells: Uint32Array;
}

async function readGrid(path: string): Promise<Grid> {
  const text = await Deno.readTextFile(path);
  const tokens = text.split(/\s+/).filter((t) => t.length > 0);

  if (tokens.length < 3) {
    fail("input must start with <width> <height> <steps>");
  }
  const width = Number(tokens[0]);
  const height = Number(tokens[1]);
  const steps = Number(tokens[2]);
  if (!Number.isInteger(width) || width < 1 || width > 512) {
    fail(`invalid width: ${tokens[0]}`);
  }
  if (!Number.isInteger(height) || height < 1 || height > 512) {
    fail(`invalid height: ${tokens[1]}`);
  }
  if (!Number.isInteger(steps) || steps < 0 || steps > 1000) {
    fail(`invalid steps: ${tokens[2]}`);
  }

  const count = width * height;
  if (tokens.length < 3 + count) {
    fail(`expected ${count} cell values, found ${tokens.length - 3}`);
  }

  const cells = new Uint32Array(count);
  for (let i = 0; i < count; i++) {
    const value = Number(tokens[3 + i]);
    if (!Number.isInteger(value) || value < 0 || value > 1000000) {
      fail(`invalid cell value at index ${i}: ${tokens[3 + i]}`);
    }
    cells[i] = value;
  }

  return { width, height, steps, cells };
}

async function diffuse(grid: Grid): Promise<Uint32Array> {
  const adapter = await navigator.gpu?.requestAdapter();
  if (!adapter) {
    fail("no WebGPU adapter available");
  }
  const device = await adapter.requestDevice();

  const byteLength = grid.cells.byteLength;
  const usage = GPUBufferUsage.STORAGE |
    GPUBufferUsage.COPY_DST |
    GPUBufferUsage.COPY_SRC;

  const buffers = [0, 1].map(() =>
    device.createBuffer({ size: byteLength, usage })
  );
  device.queue.writeBuffer(buffers[0], 0, grid.cells);

  const params = device.createBuffer({
    size: 8,
    usage: GPUBufferUsage.UNIFORM | GPUBufferUsage.COPY_DST,
  });
  device.queue.writeBuffer(
    params,
    0,
    new Uint32Array([grid.width, grid.height]),
  );

  const module = device.createShaderModule({ code: SHADER });
  const pipeline = device.createComputePipeline({
    layout: "auto",
    compute: { module, entryPoint: "main" },
  });

  // bindGroups[k] reads buffers[k] and writes buffers[1 - k].
  const bindGroups = [0, 1].map((k) =>
    device.createBindGroup({
      layout: pipeline.getBindGroupLayout(0),
      entries: [
        { binding: 0, resource: { buffer: params } },
        { binding: 1, resource: { buffer: buffers[k] } },
        { binding: 2, resource: { buffer: buffers[1 - k] } },
      ],
    })
  );

  const encoder = device.createCommandEncoder();
  const groupsX = Math.ceil(grid.width / WORKGROUP);
  const groupsY = Math.ceil(grid.height / WORKGROUP);
  for (let step = 0; step < grid.steps; step++) {
    const pass = encoder.beginComputePass();
    pass.setPipeline(pipeline);
    pass.setBindGroup(0, bindGroups[step % 2]);
    pass.dispatchWorkgroups(groupsX, groupsY);
    pass.end();
  }

  // After n steps the latest values are in buffers[n % 2].
  const result = buffers[grid.steps % 2];
  const readback = device.createBuffer({
    size: byteLength,
    usage: GPUBufferUsage.MAP_READ | GPUBufferUsage.COPY_DST,
  });
  encoder.copyBufferToBuffer(result, 0, readback, 0, byteLength);
  device.queue.submit([encoder.finish()]);

  await readback.mapAsync(GPUMapMode.READ);
  const out = new Uint32Array(readback.getMappedRange().slice(0));
  readback.unmap();

  for (const b of buffers) b.destroy();
  params.destroy();
  readback.destroy();
  device.destroy();

  return out;
}

async function main(): Promise<void> {
  const path = Deno.args[0];
  if (path === undefined) {
    fail("usage: main.ts <grid-file>");
  }

  const grid = await readGrid(path);
  const cells = grid.steps === 0
    ? grid.cells
    : await diffuse(grid);

  const lines: string[] = [];
  let sum = 0;
  for (let y = 0; y < grid.height; y++) {
    const row: number[] = new Array(grid.width);
    for (let x = 0; x < grid.width; x++) {
      const v = cells[y * grid.width + x];
      row[x] = v;
      sum += v;
    }
    lines.push(row.join(" "));
  }
  lines.push(`SUM ${sum}`);

  await Deno.stdout.write(new TextEncoder().encode(lines.join("\n") + "\n"));
}

await main();

